EXPLAIN PLAN_ADVICE
SELECT
    AVG(a) AS avg_a
FROM my_table;

EXPLAIN ESTIMATED_COST, CHANGELOG_MODE, PLAN_ADVICE, JSON_EXECUTION_PLAN
SELECT
    `count`,
    COUNT(word)
FROM my_table
GROUP BY `count`;

EXPLAIN PLAN_ADVICE
INSERT INTO my_sink
SELECT *
FROM my_source;

EXPLAIN ESTIMATED_COST, PLAN_ADVICE
EXECUTE STATEMENT SET
BEGIN
    INSERT INTO sink_a SELECT * FROM source_a;
    INSERT INTO sink_b SELECT * FROM source_b;
END;
